entry.js:
// 小红书链接解析：发出小红书分享 → 聊天里变成笔记卡片，角色读到的是笔记正文。
// 流程：跟着分享短链跳到笔记页 → 读页面里的笔记数据 → 读不到就退回从分享文案里拆标题。
var UA = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';

function toHttps(u) { return String(u || '').replace(/^http:\/\//i, 'https://'); }

function decodeEntities(s) {
  return String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, function (m, h) { return String.fromCodePoint(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (m, d) { return String.fromCodePoint(+d); })
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}

function metaOf(html, name) {
  var re = new RegExp('<meta[^>]+(?:name|property)=["\']' + name.replace(/[.:]/g, '\\$&') + '["\'][^>]*>', 'i');
  var tag = html.match(re);
  if (!tag) return '';
  var c = tag[0].match(/content="([^"]*)"/i) || tag[0].match(/content='([^']*)'/i);
  return c ? decodeEntities(c[1]).trim() : '';
}

// 页面里的 window.__INITIAL_STATE__（里面有 undefined，JSON.parse 前先换成 null）
function initialState(html) {
  var key = '__INITIAL_STATE__=';
  var i = html.indexOf(key);
  if (i < 0) return null;
  var start = i + key.length;
  var end = html.indexOf('</script>', start);
  var raw = html.slice(start, end < 0 ? undefined : end).trim().replace(/;\s*$/, '');
  try { return JSON.parse(raw.replace(/:\s*undefined\b/g, ':null').replace(/\[undefined\]/g, '[null]')); } catch (e) { return null; }
}

// 电脑版和手机版页面的数据位置不同，干脆找「长得像一篇笔记」的物件
function findNote(obj, depth) {
  if (!obj || typeof obj !== 'object' || depth > 9) return null;
  if (typeof obj.desc === 'string' && (obj.title != null || obj.displayTitle != null) && (obj.imageList || obj.user)) return obj;
  var keys = Object.keys(obj);
  for (var i = 0; i < keys.length; i++) {
    var hit = findNote(obj[keys[i]], depth + 1);
    if (hit) return hit;
  }
  return null;
}

function firstImage(n) {
  var list = n.imageList || [];
  var im = list[0];
  if (!im) return '';
  if (im.urlDefault) return im.urlDefault;
  if (im.url) return im.url;
  if (im.infoList && im.infoList.length) return im.infoList[im.infoList.length - 1].url || '';
  return im.urlPre || '';
}

// 正文里的 #话题[话题]# 标记还原成 #话题
function cleanDesc(s) {
  return String(s || '')
    .replace(/#([^#\[\n]+)\[[^\]]*\]#/g, '#$1')
    .replace(/[ \t]+\n/g, '\n').replace(/\n[ \t]+/g, '\n')   // 只有空白的行
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// 分享卡里平台那一段：「小红书 - 你的生活兴趣社区」（简繁 / rednote 都有）
var SITE_SEG = /^(?:小红书|小紅書|rednote)/i;

// 分享文案：【标题 - 作者 | 小红书 - 你的生活兴趣社区】 😆 口令 😆 链接 复制本条信息…
// 电脑版：序号 [标题 - 作者| 小紅書 - 你的生活興趣社群] 口令 链接
function fromShareText(text, url) {
  var out = { title: '', author: '', note: '' };
  var rest = String(text || '').split(url).join(' ');
  var box = rest.match(/【([^】]*)】/) || rest.match(/\[([^\[\]]*[|｜][^\[\]]*)\]/);
  if (box && /[|｜]/.test(box[1])) {
    // 标题里自己也可能有「｜」：从最后一个后面接着平台名的「|」切
    var inner = box[1];
    var cut = -1;
    var re = /[|｜]/g, m;
    while ((m = re.exec(inner))) {
      if (SITE_SEG.test(inner.slice(m.index + 1).trim())) cut = m.index;
    }
    var head = (cut >= 0 ? inner.slice(0, cut) : inner.split(/[|｜]/)[0]).trim();
    var dash = head.lastIndexOf(' - ');
    if (dash > 0) { out.title = head.slice(0, dash).trim(); out.author = head.slice(dash + 3).trim(); }
    else out.title = head;
    rest = rest.replace(box[0], ' ');
  }
  rest = rest
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/复制本条信息[\s\S]*$/, ' ')
    .replace(/[^\s]*发布了一篇小红书笔记，?快来看吧！?/g, ' ')
    .replace(/😆\s*\S+\s*😆/g, ' ');
  // 电脑版分享卡：去掉口令（一长串字母数字，带数字或多个大写）和开头的序号。
  // 只在认出分享卡格式时才做，免得删掉用户自己打的英文或数字
  if (box) {
    rest = rest
      .replace(/(^|\s)([A-Za-z0-9]{10,24})(?=\s|$)/g, function (all, sp, w) {
        return /\d/.test(w) || (w.match(/[A-Z]/g) || []).length >= 2 ? sp : all;
      })
      .replace(/(^|\s)\d{1,4}(?=\s*$)/, ' ');
  }
  rest = rest.replace(/\s+/g, ' ').trim();
  // 剩下的是用户自己附的话（新版文案没有【】，标题只能等打开笔记页才知道）
  out.note = rest;
  return out;
}

function fmtCount(v) { return v == null || v === '' ? '' : String(v); }

function buildResult(n, share, url) {
  var title = (n.title || n.displayTitle || '').trim() || share.title;
  var author = (n.user && (n.user.nickname || n.user.nickName)) || share.author;
  var desc = cleanDesc(n.desc);
  var tags = (n.tagList || n.hashTag || []).map(function (t) { return t && t.name; }).filter(Boolean);
  var info = n.interactInfo || {};
  var stats = [
    fmtCount(info.likedCount) && '点赞 ' + info.likedCount,
    fmtCount(info.collectedCount) && '收藏 ' + info.collectedCount,
    fmtCount(info.commentCount) && '评论 ' + info.commentCount
  ].filter(Boolean).join(' · ');
  var lines = [];
  lines.push('类型：' + (n.type === 'video' ? '视频笔记' : '图文笔记') + (n.imageList && n.imageList.length > 1 ? '（' + n.imageList.length + ' 张图）' : ''));
  if (desc) lines.push('正文：\n' + desc);
  // 正文末尾常已带着 #话题，全都出现过就不再重复列
  var missingTags = tags.filter(function (x) { return desc.indexOf('#' + x) < 0; });
  if (missingTags.length) lines.push('话题：' + missingTags.map(function (x) { return '#' + x; }).join(' '));
  if (stats) lines.push('互动：' + stats);
  if (share.note) lines.push('附言：' + share.note);
  return {
    title: title,
    desc: desc,
    cover: toHttps(firstImage(n)),
    site: '小红书',
    author: author,
    url: url,
    aiText: lines.join('\n')
  };
}

async function parse(d) {
  var url = d.url;
  var share = fromShareText(d.text, url);
  var page = null;
  try {
    var r = await nuo.net.fetch(toHttps(url), { headers: { 'user-agent': UA, 'accept-language': 'zh-CN,zh;q=0.9' } });
    // 被拦下的笔记会跳到 /404/ 或登录页
    if (r && r.ok && !/\/404\b|\/login/i.test(r.url || '')) page = r.body || '';
    if (r && r.url && /xiaohongshu\.com|rednote\.com/.test(r.url) && !/\/404\b/.test(r.url)) url = r.url;
  } catch (e) {
    nuo.log('打开笔记失败：' + (e && e.message));
  }
  if (page) {
    var n = findNote(initialState(page), 0);
    if (n) return buildResult(n, share, url);
    // 没有数据块，退而读 meta
    var t = metaOf(page, 'og:title').replace(/\s*-\s*(?:小红书|小紅書|rednote)\s*$/i, '');
    var ds = metaOf(page, 'description') || metaOf(page, 'og:description');
    if (t || ds) {
      return {
        title: t || share.title, desc: ds, cover: toHttps(metaOf(page, 'og:image')),
        site: '小红书', author: share.author, url: url,
        aiText: (ds ? '正文：\n' + ds : '') + (share.note ? '\n附言：' + share.note : '')
      };
    }
  }
  if (!share.title) return null;   // 什么都拿不到：照原文发
  return {
    title: share.title, desc: '', cover: '', site: '小红书', author: share.author, url: d.url,
    aiText: '（没能打开笔记正文，只看得到分享标题）' + (share.note ? '\n附言：' + share.note : '')
  };
}

nuo.link.onParse(parse);
